/**
 * @name Potential Path Traversal
 * @description Detects file opens where the path might be controlled by external input (e.g. S3 key).
 * @kind path-problem
 * @problem.severity error
 * @id py/s3transfer-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider parameters of public methods in download/manager as potential sources
    // This is a heuristic since we don't have a web app context.
    exists(Function f |
      f.getName() in ["download", "download_file", "download_fileobj"] and
      source.(DataFlow::ParameterNode).getParameter() = f.getArgByName("key")
    )
    or
    exists(Function f |
        f.getName() in ["download", "download_file", "download_fileobj"] and
        source.(DataFlow::ParameterNode).getParameter() = f.getArgByName("bucket")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "S3 key/bucket"
